patch:
diff --git a/repro-no-var-reference-error.js b/repro-no-var-reference-error.js
new file mode 100644
index 0000000..b5be9d8
--- /dev/null
+++ b/repro-no-var-reference-error.js
@@ -0,0 +1,70 @@
+/*
+ * Check for "[no-var] Fix causes ReferenceError".
+ *
+ * Applies the no-var autofix to the code from the report, then runs the result.
+ * Expected: the autofix does not turn working code into code that throws a
+ * ReferenceError (it may decline to fix, or move the declaration).
+ *
+ * Usage (from the repo root):  node repro-no-var-reference-error.js
+ * To test another ESLint build:  ESLINT_API=/path/to/eslint/lib/api.js node repro-no-var-reference-error.js
+ */
+"use strict";
+
+const path = require("node:path");
+const assert = require("node:assert");
+
+const { Linter } = require(
+	process.env.ESLINT_API || path.resolve(__dirname, "lib/api.js"),
+);
+
+const input = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+/**
+ * Runs `a()` exported from the given module source and returns the error thrown, if any.
+ * @param {string} source Module source.
+ * @returns {Promise<Error|null>} The thrown error or null.
+ */
+async function runA(source) {
+	const url = `data:text/javascript;base64,${Buffer.from(source).toString("base64")}`;
+	const originalLog = console.log;
+
+	console.log = () => {};
+	try {
+		const mod = await import(url);
+
+		mod.a();
+		return null;
+	} catch (error) {
+		return error;
+	} finally {
+		console.log = originalLog;
+	}
+}
+
+(async () => {
+	// Sanity: the original code runs fine (`var` is hoisted, `o` is undefined).
+	assert.strictEqual(await runA(input), null, "the original code should run without errors");
+
+	const linter = new Linter();
+	const result = linter.verifyAndFix(input, [{ rules: { "no-var": "error" } }]);
+
+	console.log("--- output after applying the no-var autofix ---");
+	console.log(result.output);
+
+	const error = await runA(result.output);
+
+	assert.strictEqual(
+		error,
+		null,
+		`the autofixed code throws ${error && error.name}: ${error && error.message}`,
+	);
+	console.log("OK: the autofixed code runs without errors");
+})().catch(error => {
+	console.error(`FAIL: ${error.message}`);
+	process.exitCode = 1;
+});
